43	    @Test
44	    void aNewReservationIsPendingWithItsPrice() {
45	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
46	
47	        assertEquals(ReservationStatus.PENDING, reservation.status());
48	        assertEquals(new BigDecimal("749.70"), reservation.price().total());
